/* B 端复用思路：赛事工作区 + el-table/el-tabs/el-drawer/el-form，非生产权限或资金实现。 */
(()=>{
const {icon:I,esc:E,badge:B,yuan:Y}=UI;let page='workspace',tab='overview',query='',qualification='all',task='all',routeRestoring=false,drawerFocus='',drawerReturnSelector='',drawerId=null,canOrganize=true,canPayment=true;
const active=()=>UI.s.orders.filter(o=>['submitted','approved'].includes(o.status));
const pendingFunds=()=>UI.normal()&&UI.beforeStart()?active().filter(o=>o.due>UI.net(o)):[];
const pendingReview=()=>!UI.automatic()&&UI.normal()&&UI.beforeStart()?active().filter(o=>UI.canApprove(o)):[];
const taskLabels={all:'全部报名',funds:'待核对收款',review:'待审核',closeout:'资金记录 / 收尾'};
const taskRows=t=>t==='funds'?pendingFunds():t==='review'?pendingReview():t==='closeout'?UI.s.orders.filter(o=>o.due>0||o.receipts.length||o.refunds.length):UI.s.orders;
const paidTotal=()=>UI.s.orders.reduce((n,o)=>n+UI.net(o),0);
const locked=()=>UI.s.fieldsLocked;
const primary=(action,id,label,disabled=false)=>`<button class="btn primary" data-action="${action}" data-id="${id}" ${disabled?'disabled':''}>${label}</button>`;
const general=(action,id,label)=>`<button class="btn" data-action="${action}" data-id="${id}">${label}</button>`;
const phaseText=()=>({registration:'报名中',registration_closed:'报名已截止',ongoing:'进行中',finished:'已结束'})[UI.s.phase];
function shell(body){const futurePage=page.startsWith('future-');const target=routeTarget();if(location.hash!=='#'+target){if(routeRestoring||!location.hash)history.replaceState(null,'','#'+target);else history.pushState(null,'','#'+target)}BShell.render({body,sidebar:`<span class="sidebar-label">业务空间</span><button class="space-current" data-action="workspace"><span>${I('calendar')} 赛事运营</span><span class="space-live">当前开放</span></button><span class="sidebar-label">${futurePage?'赛事快捷入口':'赛事运营'}</span><button class="sidebar-item ${page==='dashboard'?'active':''}" data-action="page" data-id="dashboard">${I('home')} 运营概览</button><button class="sidebar-item ${['workspace','events'].includes(page)?'active':''}" data-action="page" data-id="events">${I('calendar')} 赛事管理</button><button class="sidebar-item ${page==='catalog'?'active':''}" data-action="page" data-id="catalog">${I('file')} 本组织字段目录</button><span class="sidebar-label">办赛服务</span><a class="sidebar-item" href="organizer.html#status">${I('file')} 申请与准入记录</a><span class="sidebar-label">后续规划 · 未开放</span><button class="space-future ${page==='future-venues'?'active':''}" data-action="page" data-id="future-venues"><span>${I('pin')} 场馆运营</span><span>规划</span></button><button class="space-future ${page==='future-life'?'active':''}" data-action="page" data-id="future-life"><span>${I('people')} 内容与生活服务</span><span>规划</span></button>`,context:futurePage?(page==='future-venues'?'场馆运营 · 规划预览':'内容与生活服务 · 规划预览'):'赛事运营 · 莲池运动社（示例）',tools:`<button class="btn text" data-action="permissions">${I('settings')} 授权演示</button>`,active:'business',approved:true,note:'独立 HTML 界面原型。正式页面复用当前框架并按各业务空间授权；规划预告不表示功能已开放。',prototype:'界面原型 · 已准入组织示例 · 规划空间未开放实际业务'})}
function routeTarget(){const params=new URLSearchParams();if(page==='workspace'&&tab==='registrations'){if(task!=='all')params.set('task',task);if(qualification!=='all')params.set('qualification',qualification)}return (page==='workspace'?`workspace/${tab}`:page)+(params.size?'?'+params:'')}
function readRoute(){const [path,raw='']=location.hash.slice(1).split('?'),parts=path.split('/'),params=new URLSearchParams(raw);page=['workspace','dashboard','events','catalog','future-venues','future-life'].includes(parts[0])?parts[0]:'workspace';tab=page==='workspace'&&['overview','registrations','projects','fields','notifications'].includes(parts[1])?parts[1]:'overview';task=page==='workspace'&&tab==='registrations'&&Object.hasOwn(taskLabels,params.get('task'))?params.get('task'):'all';qualification=['submitted','approved','withdrawn','rejected'].includes(params.get('qualification'))?params.get('qualification'):'all';query=''}
function restoreRoute(){routeRestoring=true;readRoute();render();routeRestoring=false}

function workspace(){document.body.classList.toggle('overview-view',tab==='overview');const cancel=!UI.normal();const body=`<div class="crumb"><button class="btn text slim" data-action="page" data-id="events">赛事管理</button>${I('chevron')}<span>赛事工作区</span></div><div class="b-event-head"><div><div class="row"><span class="eyebrow">赛事工作区</span>${B(UI.s.publication==='published'?'已公开':'已下架',UI.s.publication==='published'?'':'gray')}${B(cancel?'已取消':'正常举办',cancel?'red':'gray')}${B(phaseText(),UI.s.phase==='registration'?'':'gray')}</div><h1 class="b-page-title">2026 秋季羽毛球交流赛</h1><p class="small muted">羽毛球 · 10月24日 — 10月25日 · 保定城市运动馆（示例）</p></div><div class="page-tools"><a class="btn" href="index.html?preview=1#detail">${I('user')} 公开预览</a><button class="btn" data-action="publication" ${!canOrganize||!UI.normal()||UI.s.phase==='finished'||(UI.s.publication==='published'&&UI.s.phase==='ongoing')?'disabled':''}>${UI.s.publication==='published'?'下架赛事':'恢复公开'}</button><button class="btn danger" data-action="cancel" ${!canOrganize||cancel?'disabled':''}>取消赛事</button></div></div>${cancel?`<div class="notice error mt">${I('info')}<span>赛事已取消：停止新报名、审核通过、报到、建场次、录分/确认和新证明。真实资金及通知收尾继续办理，历史保留。</span></div>`:''}<nav class="b-tabs" aria-label="赛事工作区">${[['overview','概览与发布'],['registrations','报名名单'],['projects','竞赛项目与费用'],['fields','参赛字段'],['notifications','取消通知']].map(([r,t])=>`<button class="${tab===r?'active':''}" ${tab===r?'aria-current="page"':''} data-action="tab" data-id="${r}">${t}</button>`).join('')}</nav>${tab==='overview'?overview():tab==='registrations'?registrations():tab==='projects'?projects():tab==='fields'?fields():notifications()}${UI.scenarios()}${tab==='fields'?'<div class="scenario"><span>查看锁定前的字段配置</span><button class="btn text slim" data-action="pre-submit">载入尚未提交场景（清空模拟报名）</button></div>':''}`;shell(body)}
function overview(){const n=UI.normal(),payOpen=n&&UI.beforeStart()&&canPayment,payCount=payOpen?pendingFunds().length:0,reviewCount=canOrganize?pendingReview().length:0;return `<div class="stats"><div class="stat"><span class="muted">有效报名</span><div class="num">${n?active().length:0}<span class="muted"> 单</span></div><p class="muted">按整单统计，人数另计</p></div><div class="stat"><span class="muted">${payOpen?'待核对收款':'资金记录'}</span><div class="num orange">${payOpen?payCount:taskRows('closeout').length}<span class="muted"> 单</span></div><p class="muted">付款声明不代表到账</p></div><div class="stat"><span class="muted">${n&&UI.beforeStart()?'待审核':'审核已关闭'}</span><div class="num green">${reviewCount}<span class="muted"> 单</span></div><p class="muted">收费须实际足额到账</p></div><div class="stat"><span class="muted">历史报名</span><div class="num">${UI.s.orders.length}<span class="muted"> 单</span></div><p class="muted">保留撤回、拒绝与取消</p></div></div><div class="b-grid b-overview-grid"><section class="card b-task-card"><div class="section-head"><h3>当前待办</h3>${B('按赛事办理','gray')}</div><div class="todo" data-todo="funds"><span class="todo-icon">${I('money')}</span><div class="todo-text">${payOpen?'核对 '+payCount+' 单收款':canPayment?'查看资金记录与收尾':'无资金办理权限'}<p>${payOpen?'核对实际到账后登记；声明不代表到账。':'付款入口已关闭，实际收退款记录仍保留。'}</p></div><button class="btn text" data-action="task" data-id="${payOpen?'funds':'closeout'}" ${!canPayment||payOpen&&payCount===0?'disabled':''}>${payOpen?'去办理':'查看记录'} ${I('arrow')}</button></div><div class="todo" data-todo="review"><span class="todo-icon">${I('check')}</span><div class="todo-text">${!canOrganize?'无报名审核权限':!n?'赛事已取消':!UI.beforeStart()?'审核窗口已结束':UI.automatic()?'本赛事无需人工审核':'审核 '+reviewCount+' 单报名'}<p>${reviewCount?'按本次提交资料核对资格；收费须足额到账。':'当前没有可人工审核的报名。'}</p></div><button class="btn text" data-action="task" data-id="review" ${reviewCount===0?'disabled':''}>去审核 ${I('arrow')}</button></div><div class="b-task-links"><button class="btn text slim" data-action="tab" data-id="fields">${I('file')} ${locked()?'查看已锁定配置':'检查参赛字段'}</button>${!n?'<button class="btn text slim" data-action="tab" data-id="notifications">查看取消通知</button>':''}</div></section><section class="card b-rules-card"><h3>赛事信息</h3><dl class="kv"><dt>责任组织</dt><dd>莲池运动社（示例）</dd><dt>审核方式</dt><dd>${UI.automatic()?'无需人工审核':'人工审核'} ${locked()?B('配置已锁定','gray'):''}</dd><dt>参赛字段</dt><dd>全赛事统一 · V${UI.s.configVersion}</dd></dl><details class="b-rule-details"><summary>查看办理规则与联系信息</summary><dl class="kv mt"><dt>公开联系人</dt><dd>赛事服务人员（示例）</dd><dt>资金操作</dt><dd>在报名详情内办理实际收退款</dd></dl><p class="small muted mt">已有正式报名，只允许不改变承诺的一般更正。重大变更取消原赛事后另建；已取消停止新增执行，真实资金与通知分别收尾。</p></details></section></div><section class="card mt b-overview-table"><div class="section-head"><h3>报名办理概况</h3><button class="btn text" data-action="tab" data-id="registrations">全部报名 ${I('arrow')}</button></div>${table(UI.s.orders.slice(0,3))}</section>`}

function table(rows){return `<div class="table-scroll"><table><thead><tr><th>报名编号 / 提交人</th><th>参赛项目</th><th>资格 / 当前待办</th><th>资金进度</th><th>付款声明</th><th>操作</th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${o.id}</strong><div class="sub">${E(o.person)} · ${o.submitted.slice(5)}</div></td><td>${o.unit}<div class="sub">${o.members.length} 人 / 1 单</div></td><td>${B(...UI.status(o))}${!UI.normal()?`<div class="sub">历史：${o.status==='approved'?'已通过':'已提交'}</div>`:''}</td><td><strong>${Y(UI.net(o))}</strong><span class="muted"> / ${Y(o.due)}</span><div class="sub">${o.due===0?'明确免费':UI.net(o)>=o.due?'足额有效实收':'待核对 / 补款'}</div></td><td>${o.due===0?'无需付款':o.declared?B('已声明','orange'):'未声明'}</td><td><button class="btn text" data-action="detail" data-id="${o.id}">查看办理 ${I('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="6" style="text-align:center;padding:50px;color:#77867a">暂无符合条件的报名</td></tr>'}</tbody></table></div>`}
function registrations(){const rows=taskRows(task).filter(o=>(o.person.includes(query)||o.id.includes(query))&&(qualification==='all'||o.status===qualification));return `<section class="card"><div class="section-head"><div><h3>报名名单</h3><p class="small muted" style="margin-top:5px">资格、付款声明与实际到账分别查看，费用按整单计算。</p></div>${B(`${rows.length} 单`,'gray')}</div><div class="task-filter-note"><span>当前任务：<strong>${taskLabels[task]}</strong></span><button class="btn text slim" data-action="clear-search">查看全部报名</button></div><div class="table-filters"><select id="task-filter" aria-label="任务筛选">${Object.entries(taskLabels).map(([id,t])=>`<option value="${id}" ${task===id?'selected':''}>${t}</option>`).join('')}</select><input id="search" aria-label="搜索报名" placeholder="搜索报名编号 / 提交人" value="${E(query)}"><select id="qualification" aria-label="资格筛选"><option value="all">全部资格状态</option>${[['submitted','待审 / 提交'],['approved','已通过'],['withdrawn','已撤回'],['rejected','未通过']].map(([v,t])=>`<option value="${v}" ${qualification===v?'selected':''}>${t}</option>`).join('')}</select><button class="btn" data-action="search">${I('search')} 查询</button><button class="btn text" data-action="clear-search">重置</button></div>${table(rows)}<div class="table-footer"><span>共 ${rows.length} 条 · 虚构数据</span><span class="pill-count">1</span></div></section>`}

function projects(){return `<section class="card"><div class="section-head"><h3>竞赛项目与整单费用</h3><span class="locked">${I('lock')} 本场景已有正式提交历史</span></div><div class="table-scroll"><table><thead><tr><th>项目</th><th>报名人数 / 单</th><th>容量单位</th><th>当前版本金额</th><th>收费状态</th></tr></thead><tbody>${[['男子单打','1 人',32,60],['男子双打','2 人',24,120],['女子单打','1 人',16,0]].map(([n,p,c,f])=>`<tr><td>${n}</td><td>${p}</td><td>${c} 单整单报名</td><td>${Y(UI.s.mode.endsWith('free')?0:f)}</td><td>${B(UI.s.mode.endsWith('free')||f===0?'明确免费版本':'收费版本 V1')}</td></tr>`).join('')}</tbody></table></div><div class="notice mt">${I('info')}<span>公开报价与有效收费版本同源；无配置不能按免费开放。已有历史不删除项目，容量调整不可低于实际占用。</span></div><dl class="kv mt"><dt>收款主体</dt><dd>莲池运动社（示例）</dd><dt>收款方式</dt><dd>承办方已核对的有效收款码（此原型只展示占位，不可付款）</dd><dt>退改示例</dt><dd>撤回/拒绝/取消按本次实收金额人工核对退回，确认依据后 7 个工作日办理。正式政策须由组织确认。</dd></dl><p class="route-note">B06 收费设置本轮为只读视觉稿，不模拟新收费版本写入或真实文件上传。</p></section>`}
function fields(){return `<section class="card"><div class="section-head"><div><h3>全赛事参赛字段</h3><p class="small muted" style="margin-top:5px">从本组织目录选用，所有项目使用同一字段集。</p></div><span class="locked">${I('lock')} ${locked()?'首次正式提交后已锁定':'暂无正式提交，可调整'}</span></div>${locked()?`<div class="notice neutral">${I('info')}<span>已有正式提交，字段配置与审核方式不再修改。即使全部撤回也不解锁；历史保留当时标签与含义。</span></div>`:`<div class="notice warn">${I('info')}<span>配置实质变化后，保留草稿并要求相关成员补填/重确认；仅排序不重确认。</span></div>`}<div class="field-row head mt"><span>字段</span><span>类型</span><span>必填</span><span>顺序</span></div>${UI.s.fields.map((f,i)=>`<div class="field-row"><strong>${E(f.name)}</strong><span>${f.type}</span><label aria-label="${E(f.name)}必填"><input type="checkbox" data-required="${i}" ${f.required?'checked':''} ${locked()||!canOrganize?'disabled':''}></label><span>${i+1}</span></div>`).join('')}<div class="actions"><button class="btn" data-action="page" data-id="catalog">查看本组织目录</button><button class="btn primary" data-action="save-fields" ${locked()||!canOrganize?'disabled':''}>保存配置（模拟）</button></div><p class="small muted mt">成员本人填写确认；发起人只看完成情况。每份正式提交保留值、标签、类型、单位及枚举含义。</p></section>`}
function notifications(){return `<section class="card"><div class="section-head"><h3>赛事取消通知</h3>${B(UI.normal()?'尚未取消':'已触发取消通知',UI.normal()?'gray':'red')}</div>${UI.normal()?`<div class="empty">${I('bell')}<h3>当前没有取消通知</h3><p>赛事取消后固定相关账号，并向每位相关成员投递。</p></div>`:`<div class="notice">${I('info')}<span>收件对象固定为取消时的有效关系账号并去重。短信仅发当前验证绑定号，不使用紧急联系人或第三方付款号码。</span></div><div class="table-scroll mt"><table><thead><tr><th>收件账号</th><th>站内信</th><th>本人查阅</th><th>短信</th><th>下一步</th></tr></thead><tbody><tr><td>林一（示例）</td><td>${B(UI.s.notifications.station)}</td><td>${B(UI.s.read?'已读':'未读',UI.s.read?'gray':'orange')}</td><td>${B(UI.s.notifications.sms,'orange')}</td><td><button class="btn text" data-action="notification" ${canOrganize?'':'disabled'}>模拟投递结果</button></td></tr><tr><td>周末球友（示例）</td><td>${B('已入站')}</td><td>${B('未读','orange')}</td><td>${B('无发送条件','gray')}</td><td><span class="small muted">运营渠道跟进</span></td></tr></tbody></table></div><div class="notice neutral mt">${I('clock')}<span>这里只展示收件片段，不代表完整接收人数。短信回执、已读和退款独立；超时未知先核对，失败不撤销取消。</span></div>`}</section>`}
function simplePage(){document.body.classList.remove('overview-view');if(page.startsWith('future-'))return shell(Platform.bUpcoming(page.split('-')[1]));if(page==='catalog')return shell(`<span class="eyebrow">本组织资料</span><h1 class="b-page-title">参赛字段目录</h1><p class="small muted" style="margin-bottom:24px">组织自有，不新增平台通用档案扩展目录或逐字段审批。</p><section class="card"><div class="section-head"><h3>莲池运动社 · 字段定义</h3><button class="btn primary" data-action="new-field" ${canOrganize?'':'disabled'}>新增定义</button></div><div class="table-scroll"><table><thead><tr><th>名称</th><th>类型</th><th>状态</th><th>引用与保护</th></tr></thead><tbody>${UI.s.fields.map(f=>`<tr><td>${E(f.name)}</td><td>${f.type}</td><td>${B('可用')}</td><td>赛事已选用${locked()?'且正式使用；不改含义':'；不直接删除'}</td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="btn" data-action="back-fields">返回赛事配置</button></div></section>`);if(page==='events')return shell(`<div class="between"><div><span class="eyebrow">当前组织 · 莲池运动社</span><h1 class="b-page-title">赛事管理</h1></div><button class="btn primary" data-action="new-event">新建赛事</button></div><section class="card mt"><div class="table-scroll"><table><thead><tr><th>赛事</th><th>时间</th><th>发布状态</th><th>举办状态</th><th>操作</th></tr></thead><tbody><tr><td><strong>2026 秋季羽毛球交流赛</strong><div class="sub">羽毛球 · 城市运动馆（示例）</div></td><td>10月24日 — 10月25日<div class="sub">${phaseText()}</div></td><td>${B(UI.s.publication==='published'?'已公开':'已下架','gray')}</td><td>${B(UI.normal()?'正常':'已取消',UI.normal()?'':'red')}</td><td><button class="btn text" data-action="workspace">进入工作区 ${I('arrow')}</button></td></tr></tbody></table></div></section>`);shell(`<span class="eyebrow">当前组织 · 莲池运动社</span><h1 class="b-page-title">运营概览</h1><p class="small muted" style="margin-bottom:25px">先看待办，再进入具体赛事办理。</p>${overview()}`)}
function render(){drawerId=null;UI.close();document.querySelectorAll('.drawer,.drawer-backdrop').forEach(n=>n.remove());if(page==='workspace')workspace();else simplePage()}
function drawer(id){const opener=document.activeElement;if(opener?.dataset.action==='detail')drawerReturnSelector=`[data-action="detail"][data-id="${id}"]`;const intent=task==='review'?'review':['funds','closeout'].includes(task)?'funds':'';const o=UI.order(id);if(!o)return;drawerId=id;document.querySelectorAll('.drawer,.drawer-backdrop').forEach(n=>n.remove());const [t,c]=UI.status(o),can=canOrganize&&UI.canApprove(o);const why=!UI.normal()?'赛事已取消，不允许新增通过':!UI.beforeStart()?'开赛后不允许新增通过':o.status!=='submitted'?'当前不是待审报名':UI.net(o)<o.due?'有效实收不足，暂不能通过':!canOrganize?'当前没有审核权限':'';
const html=`<div class="drawer-backdrop" data-action="close-drawer"></div><section class="drawer" role="dialog" aria-modal="true" aria-label="报名详情"><div class="drawer-head"><div class="between"><div><span class="eyebrow">报名详情 · ${o.id}</span><h2 style="margin-top:7px">${E(o.person)} · ${o.unit}</h2></div><button class="close" aria-label="关闭报名详情" data-action="close-drawer">${I('close')}</button></div><div class="row mt">${B(t,c)}${B('名单版本 V1','gray')}</div></div><div class="drawer-body"><h3>本次报名依据</h3><dl class="kv"><dt>冻结名单</dt><dd>${o.members.map(E).join('、')}</dd><dt>提交时间</dt><dd>${o.submitted} · 北京时间</dd><dt>本人确认</dt><dd>全部已确认 · 字段配置 V1</dd><dt>审核配置</dt><dd>${UI.automatic()?'无需人工审核':'人工审核'} · 首次提交已锁定</dd><dt>报到 / 场次</dt><dd>${o.checked?'有成员报到':'全单未报到'} / ${o.match?'有场次关联':'无场次关联'}</dd></dl><section class="card" id="drawer-review" tabindex="-1" aria-label="资格审核办理"><div class="section-head"><h3>资格审核</h3>${B('审核权限','gray')}</div><p class="small muted">资金满足后，人工审核仍需核对本次冻结依据。用户付款声明不作到账证据。</p>${why?`<div class="notice ${o.status==='approved'?'neutral':'warn'} mt">${I('info')}<span>${why}</span></div>`:''}<div class="actions">${!UI.automatic()?primary('approve',id,'审核通过（模拟）',!can):`<span class="small muted">无需审核：到账后由服务端重验自动通过</span>`}<button class="btn danger" data-action="reject" data-id="${id}" ${canOrganize&&o.status==='submitted'?'':'disabled'}>拒绝</button></div></section><section class="card" id="drawer-funds" tabindex="-1" aria-label="收退款办理"><div class="section-head"><h3>本次费用与资金</h3>${B('资金权限','gray')}</div><div class="status-grid"><div class="status-item"><p>整单应付</p><strong>${Y(o.due)}</strong></div><div class="status-item"><p>净有效实收</p><strong>${Y(UI.net(o))}</strong></div><div class="status-item"><p>实际退款累计</p><strong>${Y(UI.refunded(o))}</strong></div></div><div class="between mt"><span class="small muted">用户付款声明</span>${B(o.due===0?'无需付款':o.declared?'已声明':'未声明','gray')}</div><div class="between mt"><span class="small muted">退款办理</span>${B(UI.refundLabel(o),'gray')}</div>${!canPayment?`<div class="notice neutral mt">${I('lock')}<span>当前没有资金办理权限，不能新增、冲正或登记退款；正式接口也需校验用途范围。</span></div>`:`<div class="actions">${general('receipt',id,o.receipts.length?'登记真实补款':'登记真实收款')}${general('refund',id,'实际退款登记')}</div>`}<div class="line"></div><h4 class="small">资金事实记录</h4>${o.receipts.map(r=>`<div class="b-record"><div class="between"><strong>${r.reversed?'已冲正':'实际收款'} ${Y(r.amount)}</strong>${canPayment&&!r.reversed?`<button class="btn text" data-action="reverse" data-id="${id}" data-receipt="${r.id}">冲正</button>`:B(r.reversed?'无效实收':'有效实收',r.reversed?'gray':'')}</div><p class="muted small">付款人 ${E(r.payer)} · ${E(r.time)}</p></div>`).join('')||'<p class="small muted mt">暂无实际到账记录。不能从声明或应付值伪造到账。</p>'}${o.refunds.map(r=>`<div class="b-record"><strong>实际退款 ${Y(r.amount)}</strong><p class="small muted">接收人 ${E(r.recipient)} · ${E(r.time)} · 对应原收款 ${E(r.source)}</p></div>`).join('')}<p class="entry-note mt">退改依据快照：合法撤回、拒绝或取消按实收金额人工核对退款。原型所有资金只在本地模拟。</p></section>${o.status==='approved'&&o.due>UI.net(o)?`<div class="notice warn mt">${I('info')}<span>${o.checked||o.match?'已有报到/场次关联，需人工协调，不删除既有事实。':'付款不足，暂停新报到。补足仅解除付款限制，不恢复其他失效条件。'}</span></div>`:''}</div><div class="drawer-foot between"><span class="small muted">操作集中本报名，不跨单抵扣</span><button class="btn" data-action="close-drawer">关闭</button></div></section>`;document.body.insertAdjacentHTML('beforeend',html);if(intent)requestAnimationFrame(()=>{const target=document.getElementById('drawer-'+intent);target?.scrollIntoView({block:'start'});target?.focus({preventScroll:true})});else document.querySelector('.drawer .close')?.focus()}
function refresh(id){render();if(id)drawer(id)}
function receiptForm(id){const o=UI.order(id);if(!canPayment)return;UI.modal('登记实际收款 · 本地模拟',`<div class="notice warn">${I('info')}<span>真实产品应先核对平台外实际到账，再登记。以下不发生真实资金变动。</span></div><form id="receipt-form" class="mt"><label class="label"><span>实际付款人 <b>*</b></span><input name="payer" required maxlength="40" placeholder="核对实际付款人，不默认参赛者"></label><div class="grid2"><label class="label"><span>实际金额（元） <b>*</b></span><input name="amount" type="number" min="0.01" max="100000" step="0.01" required placeholder="填写实际金额"></label><label class="label"><span>实际发生时间 <b>*</b></span><input name="time" type="datetime-local" required></label></div><label class="checkline"><input name="confirmed" type="checkbox" required><span>我已核对实际付款人、金额及到账时间。</span></label><button type="submit" class="btn primary">登记收款（模拟）</button></form>`);document.getElementById('receipt-form').onsubmit=ev=>{ev.preventDefault();if(!canPayment)return;const f=new FormData(ev.target);UI.change(()=>o.receipts.push({id:'REC-'+Date.now(),payer:f.get('payer').trim(),amount:Number(f.get('amount')),time:f.get('time').replace('T',' '),reversed:false}));refresh(id);UI.toast(o.status==='approved'?'模拟到账重验后已自动通过。':'模拟实收已登记；资格状态另行办理。')}}
function refundForm(id){const o=UI.order(id);if(!canPayment)return;const eligible=o.receipts.filter(r=>!r.reversed&&r.amount>o.refunds.filter(x=>x.source===r.id).reduce((n,x)=>n+x.amount,0));if(!eligible.length){UI.toast('没有可退款的有效实际收款；不能凭应付值登记退款。');return}if(UI.normal()&&!['withdrawn','rejected'].includes(o.status)){UI.toast('本轮演示退改政策适用于撤回、拒绝或取消；请先明确退款依据。');return}UI.modal('登记已实际完成的退款',`<div class="notice warn">${I('info')}<span>先在平台外实际退款，再登记事实。部分退款仍为办理中，不提前结案。</span></div><form id="refund-form" class="mt"><label class="label"><span>对应原收款与付款人 <b>*</b></span><select name="source">${eligible.map(r=>`<option value="${r.id}">${E(r.payer)} · ${Y(r.amount)} · ${r.id}</option>`).join('')}</select></label><label class="label"><span>实际退款接收人 <b>*</b></span><input name="recipient" required placeholder="核对原付款人"></label><div class="grid2"><label class="label"><span>实际退款金额（元） <b>*</b></span><input name="amount" type="number" min="0.01" step="0.01" required></label><label class="label"><span>实际退款时间 <b>*</b></span><input name="time" type="datetime-local" required></label></div><p class="field-error" id="refund-error"></p><label class="checkline"><input type="checkbox" required><span>我已核对原付款人并完成本次平台外退款。</span></label><button type="submit" class="btn primary">登记实际退款（模拟）</button></form>`);document.getElementById('refund-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),r=o.receipts.find(x=>x.id===f.get('source'));const amount=Number(f.get('amount')),available=r.amount-o.refunds.filter(x=>x.source===r.id).reduce((n,x)=>n+x.amount,0);if(amount>available||amount>UI.net(o)){document.getElementById('refund-error').textContent='实际累计退款不得超过所选有效收款或本单有效实收。';return}if(f.get('recipient').trim()!==r.payer){document.getElementById('refund-error').textContent='接收人与原付款人不符。变更需另行核验授权依据，本原型不模拟该例外。';return}UI.change(()=>{o.refunds.push({source:r.id,recipient:f.get('recipient'),amount,time:f.get('time').replace('T',' ')});o.refundState=UI.net(o)===0?'done':'progress'});refresh(id);UI.toast('模拟实际退款记录已保存；未退完仍为办理中。')}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,id=el.dataset.id;
if(a==='page'){page=id;render()}else if(a==='task'){task=id;qualification='all';query='';page='workspace';tab='registrations';render()}else if(a==='workspace'){page='workspace';tab='overview';render()}else if(a==='tab'){page='workspace';tab=id;if(id==='registrations'){task='all';qualification='all';query=''}render()}else if(a==='back-fields'){page='workspace';tab='fields';render()}else if(a==='detail')drawer(id);else if(a==='close-drawer'){drawerId=null;document.querySelectorAll('.drawer,.drawer-backdrop').forEach(n=>n.remove());document.querySelector(drawerReturnSelector)?.focus()}else if(a==='search'){query=document.getElementById('search').value.trim();qualification=document.getElementById('qualification').value;task=document.getElementById('task-filter').value;workspace()}else if(a==='clear-search'){query='';qualification='all';task='all';workspace()}else if(a==='receipt')receiptForm(id);else if(a==='refund')refundForm(id);else if(a==='approve'){const o=UI.order(id);if(!canOrganize||!UI.canApprove(o)){UI.toast('当前条件不允许通过。');return}UI.change(()=>o.status='approved');refresh(id);UI.toast('模拟人工审核已通过；资金事实仍独立保留。')}else if(a==='reject'){UI.modal('拒绝这单报名',`<form id="reject-form"><label class="label"><span>拒绝理由 <b>*</b></span><textarea name="reason" required placeholder="填写真实业务理由，不把声明待核对当未付款"></textarea></label><p class="small muted">拒绝释放名额，真实款项按原退改依据人工收尾。</p><button type="submit" class="btn danger">确认拒绝（模拟）</button></form>`);document.getElementById('reject-form').onsubmit=ev=>{ev.preventDefault();const o=UI.order(id);if(!canOrganize||o.status!=='submitted')return;UI.change(()=>{o.status='rejected';o.rejectionReason=new FormData(ev.target).get('reason');if(UI.net(o)>0)o.refundState='pending'});refresh(id);UI.toast('模拟已拒绝；未自动生成退款事实。')}}else if(a==='reverse'){const o=UI.order(id),r=o.receipts.find(x=>x.id===el.dataset.receipt);if(!canPayment)return;if(o.refunds.some(x=>x.source===r.id)||UI.net(o)<r.amount){UI.toast('该款已有退款或冲正会造成超额退款，先人工核对受控修复。');return}UI.modal('确认冲正这笔收款？',`<p>原收款 ${Y(r.amount)} · ${E(r.payer)}。冲正保留原事实，不是删除记录。</p><div class="notice warn mt">${I('info')}<span>若通过报名实收不足：无人报到/无场次暂停新报到；已有执行需人工协调。</span></div>`,`<button class="btn" data-action="close">暂不冲正</button><button class="btn danger" data-action="confirm-reverse" data-id="${id}" data-receipt="${r.id}">冲正（模拟）</button>`)}else if(a==='confirm-reverse'){const o=UI.order(id),r=o.receipts.find(x=>x.id===el.dataset.receipt);if(!canPayment||r.reversed||o.refunds.some(x=>x.source===r.id))return;UI.change(()=>r.reversed=true);refresh(id);UI.toast('模拟冲正已记录；原收款及资格历史未删除。')}else if(a==='cancel'){UI.modal('确认取消整场赛事？',`<p>将停止新增报名、审核通过、报到、建场次、录分/确认和新证明。历史保留，不能恢复举办。</p><div class="notice warn mt">${I('money')}<span>资金按原依据人工收尾。取消不代表已经退款，也不等待短信送达。</span></div>`,`<button class="btn" data-action="close">暂不取消</button><button class="btn danger" data-action="confirm-cancel">确认取消（模拟）</button>`)}else if(a==='confirm-cancel'){if(!canOrganize||!UI.normal())return;UI.change(s=>{s.hosting='cancelled';s.orders.forEach(o=>{if(UI.net(o)>0)o.refundState='pending'});s.notifications={station:'已入站',sms:'待发送'}});render();UI.toast('模拟赛事已取消；通知与资金收尾分别处理。')}else if(a==='publication'){if(!canOrganize||!UI.normal()||UI.s.phase==='finished')return;if(UI.s.publication==='published'&&UI.s.phase==='ongoing')return;UI.change(s=>s.publication=s.publication==='published'?'offline':'published');render();UI.toast(UI.s.publication==='published'?'模拟恢复公开，不重开报名，不修改旧义务。':'模拟已下架，原报名义务和本人访问保留。')}else if(a==='permissions'){UI.modal('授权演示 · 不是真实权限设置',`<p class="small muted">两项动作权限可以由同人兼任，互不自动包含。</p><form id="permission-form" class="mt"><label class="checkline"><input name="organize" type="checkbox" ${canOrganize?'checked':''}><span>organize · 组织办理/审核</span></label><label class="checkline"><input name="payment" type="checkbox" ${canPayment?'checked':''}><span>payment · 资金写操作</span></label><button type="submit" class="btn primary">切换演示授权</button></form>`);document.getElementById('permission-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target);canOrganize=f.has('organize');canPayment=f.has('payment');render();UI.toast('已切换原型权限；真实权限由现有框架及服务端控制。')}}else if(a==='save-fields'){if(locked()||!canOrganize)return;UI.change(s=>{s.fields.forEach((f,i)=>f.required=document.querySelector(`[data-required="${i}"]`).checked);s.configVersion++});render();UI.toast('模拟配置版本已更新；正式链需成员补填/重确认。')}else if(a==='new-field'){UI.modal('新增组织字段定义',`<form id="field-form"><label class="label"><span>字段名称 <b>*</b></span><input name="name" required maxlength="25"></label><label class="label"><span>字段类型</span><select name="type"><option>文本</option><option>数字</option><option>日期</option><option>单选枚举</option></select></label><p class="small muted">本轮只展示新增表单，单位与枚举含义配置及真实定义保存待后续实现。</p><button type="submit" class="btn primary">预览定义（模拟）</button></form>`);document.getElementById('field-form').onsubmit=ev=>{ev.preventDefault();UI.close();UI.toast('表单预览完成；本轮不写入真实或模拟目录。')}}else if(a==='notification'){UI.modal('短信渠道状态演示',`<p class="muted small">不实际发送短信。超时未知先查询回执，明确暂时失败才有限重试。</p><div class="actions">${general('sms-state','已送达','已送达')}${general('sms-state','暂时失败','暂时失败')}${general('sms-state','回执待确认','超时未知')}</div>`)}else if(a==='sms-state'){UI.change(s=>s.notifications.sms=id);render();UI.toast('仅更新模拟渠道状态。')}else if(a==='reset'){UI.reset();page='workspace';tab='overview';render();UI.toast('已重置虚构数据。')}else if(a==='pre-submit'){UI.reset();UI.change(s=>{s.orders=[];s.fieldsLocked=false});render();UI.toast('已载入提交前的虚构场景；正式提交后不能这样解锁。')}else if(a==='new-event')UI.modal('新建赛事 · 后续线框',`<p>本轮重点为已有赛事的工作区、报名审核与资金详情。新建/编辑表单沿既有业务，下一轮再细化。</p>`)
});
document.addEventListener('change',e=>{if(e.target.dataset.scenario==='mode'){UI.reset(e.target.value);render();UI.toast('载入另一组虚构数据；不是编辑已锁定的真实审核配置。')}if(e.target.dataset.scenario==='phase'){UI.change(s=>s.phase=e.target.value);render()}});
window.addEventListener('storage',e=>{if(UI.syncFromStorage(e))render()});window.addEventListener('hashchange',restoreRoute);window.addEventListener('popstate',restoreRoute);restoreRoute();
})();

